/// How long an animation runs. Each picks the duration for what it is, never by feel; the speed
/// setting scales them all.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Duration {
    /// Changes that must not lag: the caret, text appearing as it is typed, reduce motion's moves.
    Instant,
    /// Hover and press state layers, a colour change under the pointer.
    Micro,
    /// A toggle's knob, a checkbox's mark, focus moving, a toast fading in.
    Short,
    /// A panel or popup leaving, a log opening, a list reordering, a toast fading out.
    Medium,
    /// A panel or dialog arriving, a page sliding in.
    Long,
    /// A wallpaper fading in, the light/dark crossfade.
    Slow,
    /// A whole scene changing once: the lock screen lifting, Kōbō's welcome settling.
    Scene,
}

impl Duration {
    /// Every duration.
    pub const ALL: [Duration; 7] = [
        Duration::Instant,
        Duration::Micro,
        Duration::Short,
        Duration::Medium,
        Duration::Long,
        Duration::Slow,
        Duration::Scene,
    ];

    /// The duration in milliseconds, at speed 1.
    pub const fn ms(self) -> u32 {
        match self {
            Duration::Instant => 0,
            Duration::Micro => 100,
            Duration::Short => 200,
            Duration::Medium => 300,
            Duration::Long => 500,
            Duration::Slow => 800,
            Duration::Scene => 1200,
        }
    }
}

/// An easing curve.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Easing {
    /// Things leaving the screen: panels and dialogs closing.
    EmphasizedAccel,
    /// Things arriving on screen: panels, dialogs, pages, the log opening.
    EmphasizedDecel,
    /// Progress that tracks a real quantity, and spinners.
    Linear,
    /// Small state changes that stay on screen: toggles, colour, focus.
    Standard,
    /// Something small leaving for good: a toast fading out.
    StandardAccel,
    /// Something already moving settling in: a list reordering.
    StandardDecel,
}

